using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Preserve "Discriminator" to remain compatible with existing 500K documents
            // and direct SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 breaking change #2: Id format changed from "EntityType|Key" to just "Key".
            // Existing documents use "Product|123" format. Override id generation to keep
            // compatibility and avoid phantom duplicates / missed reads.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            // EF Core 9 breaking change #3: HasIndex() for Cosmos now tries to use
            // container indexing policy. Remove or replace with manual indexing policy config.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

// Preserves the legacy "Product|<key>" id format used by EF Core 8
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var product = (Product)entry.Entity;
        return $"Product|{product.Id}";
    }
}

